pub fn dashboard_instance_answers_host_lookup(instance: Rc<HostDashboardInstance>) -> bool {
    match (*instance.source_seed.clone()).clone() {
    DashboardSourceSeed::DashboardExistingRepo { anchor_ref: _, .. } => true,
    DashboardSourceSeed::DashboardSeededByConvergence { .. } => false,
    DashboardSourceSeed::DashboardGitBundle { .. } => false,
}
}

pub fn dashboard_instance_for_host(host: String) -> Rc<DashboardInstanceByHost> {
    match Rc::new({ let mut __result = Vec::new(); for i in public_builtin_dashboard_instances().iter().cloned() { if ((i.host_identity.clone() == host.clone()) && dashboard_instance_answers_host_lookup(i.clone())) { __result.push(i); } } __result }).first().cloned() {
    Some(instance) => Rc::new(DashboardInstanceByHost::DashboardInstanceForHost {
    instance: instance.clone(),
}),
    std::option::Option::None => Rc::new(DashboardInstanceByHost::DashboardInstanceHostUnknown {
    host: host.clone(),
}),
}
}

