#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ProdRoleRealizationRefusal {
    ProdRoleUnheld,
    ProdRoleHolderUnrealized {
        deployment: Rc<DeploymentId>,
    },
    ProdRoleHolderAmbiguous {
        deployment: Rc<DeploymentId>,
        count: i64,
    },
    ProdRoleHolderUnactuatable {
        deployment: Rc<DeploymentId>,
    },
}
impl ProdRoleRealizationRefusal {
    pub fn deployment(&self) -> Rc<DeploymentId> {
        match self {
            ProdRoleRealizationRefusal::ProdRoleUnheld => panic!("no deployment on unit variant"),
            ProdRoleRealizationRefusal::ProdRoleHolderUnrealized { deployment: __val, .. } => __val.clone(),
            ProdRoleRealizationRefusal::ProdRoleHolderAmbiguous { deployment: __val, .. } => __val.clone(),
            ProdRoleRealizationRefusal::ProdRoleHolderUnactuatable { deployment: __val, .. } => __val.clone(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct ProdRoleHolder {
    instance: Rc<HostDashboardInstance>,
}
impl ProdRoleHolder {
    pub fn instance(&self) -> Rc<HostDashboardInstance> {
        self.instance.clone()
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum ProdRoleRealization {
    ProdRoleRealizedBy {
        holder: Rc<ProdRoleHolder>,
    },
    ProdRoleRealizationRefused {
        cause: Rc<ProdRoleRealizationRefusal>,
    },
}

pub fn prod_role_realization_in(selection: Rc<ProdRoleSelection>, instances: Rc<Vec<Rc<HostDashboardInstance>>>) -> Rc<ProdRoleRealization> {
    match (*selection.clone()).clone() {
    ProdRoleSelection::NoProdRole => Rc::new(ProdRoleRealization::ProdRoleRealizationRefused {
    cause: Rc::new(ProdRoleRealizationRefusal::ProdRoleUnheld),
}),
    ProdRoleSelection::ProdRoleHeldBy { deployment: holder, .. } => {
        let realizing = Rc::new({ let mut __result = Vec::new(); for i in instances.iter().cloned() { if (i.deployment.clone() == holder.clone()) { __result.push(i); } } __result });
match realizing.clone().first().cloned() {
    std::option::Option::None => Rc::new(ProdRoleRealization::ProdRoleRealizationRefused {
    cause: Rc::new(ProdRoleRealizationRefusal::ProdRoleHolderUnrealized {
    deployment: holder.clone(),
}),
}),
    Some(only) => if ((realizing.clone().len() as i64) == 1) {
            Rc::new(ProdRoleRealization::ProdRoleRealizedBy {
    holder: Rc::new(ProdRoleHolder {
    instance: only.clone(),
}),
})
        } else {
            Rc::new(ProdRoleRealization::ProdRoleRealizationRefused {
    cause: Rc::new(ProdRoleRealizationRefusal::ProdRoleHolderAmbiguous {
    deployment: holder.clone(),
    count: (realizing.clone().len() as i64),
}),
})
        },
}
},
}
}

pub fn prod_role_realization() -> Rc<ProdRoleRealization> {
    prod_role_realization_in(prod_role_selection(), public_builtin_dashboard_instances())
}

pub fn prod_role_realization_refusal_detail(cause: Rc<ProdRoleRealizationRefusal>) -> String {
    match (*cause.clone()).clone() {
    ProdRoleRealizationRefusal::ProdRoleUnheld => "prod role refused: prod_role_selection is NoProdRole; no deployment holds it".to_string(),
    ProdRoleRealizationRefusal::ProdRoleHolderUnrealized { deployment: deployment, .. } => Rc::new(vec!["prod role refused: holder ".to_string(), deployment.name.clone(), " has no HostDashboardInstance".to_string()]).join(&"".to_string()),
    ProdRoleRealizationRefusal::ProdRoleHolderAmbiguous { deployment, count: n, .. } => Rc::new(vec!["prod role refused: holder ".to_string(), deployment.name.clone(), " has ".to_string(), (n.clone()).to_string(), " instances".to_string()]).join(&"".to_string()),
    ProdRoleRealizationRefusal::ProdRoleHolderUnactuatable { deployment: deployment, .. } => Rc::new(vec!["prod role refused: holder ".to_string(), deployment.name.clone(), " has no desired deployment row (gunbc.live_deploy.desired desired_deployment_roster), so nothing can actuate it".to_string()]).join(&"".to_string()),
}
}

