#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct DashboardGitConfigPosturePair {
    pub key: NonEmptyStr,
    pub value: String,
}

pub fn dashboard_git_shared_repository_posture_document(pairs: Rc<Vec<Rc<DashboardGitConfigPosturePair>>>, service_unit_document: String, timer_unit_document: String) -> String {
    {
        let key_section = Rc::new({ let mut __result = Vec::new(); for p in pairs.iter().cloned() { __result.push(Rc::new(vec![p.key.clone(), "=".to_string(), p.value.clone()]).join(&"".to_string())); } __result });
let unit_section = Rc::new(vec![Rc::new(vec!["service-unit=".to_string(), service_unit_document.clone()]).join(&"".to_string()), Rc::new(vec!["timer-unit=".to_string(), timer_unit_document.clone()]).join(&"".to_string())]);
v1_rt::concat(key_section.clone(), unit_section.clone()).join(&"\n".to_string())
}
}

