#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum DashboardGitSubtreeReadbackLine {
    ReadbackSubtreeTop {
        mode: Rc<FileMode>,
        group: NonEmptyStr,
    },
    ReadbackInteriorDirectory {
        mode: Rc<FileMode>,
        group: NonEmptyStr,
        path: NonEmptyStr,
    },
    ReadbackEntryFile {
        mode: Rc<FileMode>,
        group: NonEmptyStr,
        path: NonEmptyStr,
    },
}
impl DashboardGitSubtreeReadbackLine {
    pub fn mode(&self) -> Rc<FileMode> {
        match self {
            DashboardGitSubtreeReadbackLine::ReadbackSubtreeTop { mode: __val, .. } => __val.clone(),
            DashboardGitSubtreeReadbackLine::ReadbackInteriorDirectory { mode: __val, .. } => __val.clone(),
            DashboardGitSubtreeReadbackLine::ReadbackEntryFile { mode: __val, .. } => __val.clone(),
        }
    }
    pub fn group(&self) -> NonEmptyStr {
        match self {
            DashboardGitSubtreeReadbackLine::ReadbackSubtreeTop { group: __val, .. } => __val.clone(),
            DashboardGitSubtreeReadbackLine::ReadbackInteriorDirectory { group: __val, .. } => __val.clone(),
            DashboardGitSubtreeReadbackLine::ReadbackEntryFile { group: __val, .. } => __val.clone(),
        }
    }
}

pub fn dashboard_git_subtree_readback_line(line: String) -> Option<Rc<DashboardGitSubtreeReadbackLine>> {
    {
        let legs = Rc::new(line.clone().split(&" ".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
match legs.clone().first().cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(letter) => match legs.clone().get((1) as usize).cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(printed_mode) => match legs.clone().get((2) as usize).cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(printed_group) => if (v1_rt::trim(printed_group.clone()) == "".to_string()) {
            std::option::Option::None
        } else {
            match crate::extdeps_access_posix::file_mode_of_octal_text(v1_rt::trim(printed_mode.clone())) {
    std::option::Option::None => std::option::Option::None,
    Some(mode) => {
                let path = Rc::new(v1_rt::list_skip(&legs.clone(), 3)).join(&" ".to_string());
let group = v1_rt::trim(printed_group.clone());
if (letter.clone() == find_printf_type_directory_letter()) {
                    if (path.clone() == "".to_string()) {
                        Some(Rc::new(DashboardGitSubtreeReadbackLine::ReadbackSubtreeTop {
    mode: mode.clone(),
    group: group.clone(),
}))
                    } else {
                        Some(Rc::new(DashboardGitSubtreeReadbackLine::ReadbackInteriorDirectory {
    mode: mode.clone(),
    group: group.clone(),
    path: path.clone(),
}))
                    }
                } else {
                    if (letter.clone() == find_printf_type_regular_file_letter()) {
                        if (path.clone() == "".to_string()) {
                            std::option::Option::None
                        } else {
                            Some(Rc::new(DashboardGitSubtreeReadbackLine::ReadbackEntryFile {
    mode: mode.clone(),
    group: group.clone(),
    path: path.clone(),
}))
                        }
                    } else {
                        std::option::Option::None
                    }
                }
},
}
        },
},
},
}
}
}

pub fn dashboard_git_subtree_readback_is_granted(child: String, group: String, receipt: String) -> bool {
    dashboard_git_subtree_readback_is_granted_under(dashboard_git_worker_subtree_granted_directory_mode(child.clone()), group, dashboard_git_worker_subtree_writes_files_in_place(child.clone()), receipt)
}

pub fn dashboard_git_subtree_readback_is_granted_under(top: Rc<FileMode>, group: String, files_group_writable: bool, receipt: String) -> bool {
    {
        let lines = Rc::new({ let mut __result = Vec::new(); for l in Rc::new(receipt.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned() { if (v1_rt::trim(l.clone()) != "".to_string()) { __result.push(l); } } __result });
let parsed = Rc::new({ let mut __result = Vec::new(); for l in lines.iter().cloned() { __result.push(dashboard_git_subtree_readback_line(l.clone())); } __result });
((((((parsed.clone().len() as i64) > 0) && { let mut __all = true; for entry in parsed.iter().cloned() { if !(match entry.clone() {
    std::option::Option::None => false,
    Some(_) => true,
}) { __all = false; break; } } __all }) && { let mut __found = false; for entry in parsed.iter().cloned() { if match entry.clone() {
    std::option::Option::None => false,
    Some(line) => match (*line.clone()).clone() {
    DashboardGitSubtreeReadbackLine::ReadbackSubtreeTop { .. } => true,
    DashboardGitSubtreeReadbackLine::ReadbackInteriorDirectory { .. } => false,
    DashboardGitSubtreeReadbackLine::ReadbackEntryFile { .. } => false,
},
} { __found = true; break; } } __found }) && { let mut __all = true; for entry in parsed.iter().cloned() { if !(match entry.clone() {
    std::option::Option::None => false,
    Some(line) => (line_group_of(line.clone()) == group.clone()),
}) { __all = false; break; } } __all }) && { let mut __all = true; for entry in parsed.iter().cloned() { if !(match entry.clone() {
    std::option::Option::None => false,
    Some(line) => match (*line.clone()).clone() {
    DashboardGitSubtreeReadbackLine::ReadbackSubtreeTop { mode, .. } => dashboard_git_worker_file_modes_are_equal(mode.clone(), top.clone()),
    DashboardGitSubtreeReadbackLine::ReadbackInteriorDirectory { mode, .. } => dashboard_git_worker_interior_directory_mode_is_accepted(mode.clone()),
    DashboardGitSubtreeReadbackLine::ReadbackEntryFile { mode, .. } => if files_group_writable.clone() {
            dashboard_git_worker_file_mode_is_granted(mode.clone())
        } else {
            dashboard_git_worker_readonly_file_mode_is_accepted(mode.clone())
        },
},
}) { __all = false; break; } } __all })
}
}

pub fn line_group_of(line: Rc<DashboardGitSubtreeReadbackLine>) -> String {
    match (*line.clone()).clone() {
    DashboardGitSubtreeReadbackLine::ReadbackSubtreeTop { group, .. } => group.clone(),
    DashboardGitSubtreeReadbackLine::ReadbackInteriorDirectory { group, .. } => group.clone(),
    DashboardGitSubtreeReadbackLine::ReadbackEntryFile { group, .. } => group.clone(),
}
}

